function solve(tree, k) {
  const sorted = [];
  function inorder(idx) {
    if (idx >= tree.length || tree[idx] === null) return;
    inorder(2 * idx + 1);
    sorted.push(tree[idx]);
    inorder(2 * idx + 2);
  }
  inorder(0);
  return sorted[k - 1];
}
